{
  "headline": "FDA's records trace our supply to a plant classified OAI 2819 days before the posting",
  "headline_cites": ["D4"],
  "sentences": [
    {
      "text": "FDA first posted the dopamine hydrochloride shortage on 2017-11-06 and it remains Current as of 2026-10-21.",
      "cites": ["E22", "E19", "E20", "E21"]
    },
    {
      "text": "The shortage has been on FDA's list for 108 months as of 2026-10-21.",
      "cites": ["D6"]
    },
    {
      "text": "Hospira, Inc. (FEI 1021343) is a registered manufacturer for this product and its plant was classified OAI on 2010-01-19, 2011-06-17, and 2011-08-04.",
      "cites": ["E18", "E8", "E10", "E12"]
    },
    {
      "text": "The earliest OAI classification at this plant occurred 2819 days before the shortage posting on 2017-11-06.",
      "cites": ["D4"]
    },
    {
      "text": "Hikma Pharmaceuticals USA Inc. and Baxter Healthcare also appear on FDA's shortage list with Current status.",
      "cites": ["E19", "E20", "E21"]
    },
    {
      "text": "HF Acquisition Co LLC, DBA HealthFirst is not on FDA's shortage list today and its label names no plant we could place.",
      "cites": ["D7"]
    },
    {
      "text": "Check inventory at Corvale East (12.3 days on hand), Corvale General (11.7 days), and Corvale Lakeside (13.8 days) and evaluate the alternate manufacturer option.",
      "cites": ["D1", "D2", "D3", "D7"]
    }
  ]
}
